{
  "files": {
    "registration.php": "<?php\ndeclare(strict_types=1);\n\nuse Magento\\Framework\\Component\\ComponentRegistrar;\n\nComponentRegistrar::register(\n    ComponentRegistrar::MODULE,\n    'Vendor_B2BModule',\n    __DIR__\n);",
    "etc/module.xml": "<?xml version=\"1.0\"?>\n<config xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"\n        xsi:noNamespaceSchemaLocation=\"urn:magento:framework:Module/etc/module.xsd\">\n    <module name=\"Vendor_B2BModule\">\n        <sequence>\n            <module name=\"Magento_Catalog\"/>\n            <module name=\"Magento_Eav\"/>\n        </sequence>\n    </module>\n</config>",
    "Setup/Patch/Data/AddGrossWeightAttribute.php": "<?php\ndeclare(strict_types=1);\n\nnamespace Vendor\\B2BModule\\Setup\\Patch\\Data;\n\nuse Magento\\Eav\\Model\\Entity\\Attribute\\ScopedAttributeInterface;\nuse Magento\\Eav\\Setup\\EavSetup;\nuse Magento\\Eav\\Setup\\EavSetupFactory;\nuse Magento\\Framework\\Setup\\ModuleDataSetupInterface;\nuse Magento\\Framework\\Setup\\Patch\\DataPatchInterface;\nuse Magento\\Framework\\Setup\\Patch\\PatchRevertableInterface;\n\n/**\n * Data patch to create gross_weight product attribute\n */\nclass AddGrossWeightAttribute implements DataPatchInterface, PatchRevertableInterface\n{\n    /**\n     * @var ModuleDataSetupInterface\n     */\n    private ModuleDataSetupInterface $moduleDataSetup;\n\n    /**\n     * @var EavSetupFactory\n     */\n    private EavSetupFactory $eavSetupFactory;\n\n    /**\n     * @param ModuleDataSetupInterface $moduleDataSetup\n     * @param EavSetupFactory $eavSetupFactory\n     */\n    public function __construct(\n        ModuleDataSetupInterface $moduleDataSetup,\n        EavSetupFactory $eavSetupFactory\n    ) {\n        $this->moduleDataSetup = $moduleDataSetup;\n        $this->eavSetupFactory = $eavSetupFactory;\n    }\n\n    /**\n     * @inheritdoc\n     */\n    public function apply(): void\n    {\n        /** @var EavSetup $eavSetup */\n        $eavSetup = $this->eavSetupFactory->create(['setup' => $this->moduleDataSetup]);\n\n        $eavSetup->addAttribute(\n            \\Magento\\Catalog\\Model\\Product::ENTITY,\n            'gross_weight',\n            [\n                'type' => 'decimal',\n                'label' => 'Gross Weight',\n                'input' => 'text',\n                'required' => false,\n                'sort_order' => 100,\n                'global' => ScopedAttributeInterface::SCOPE_GLOBAL,\n                'group' => 'Product Details',\n                'is_used_in_grid' => true,\n                'is_visible_in_grid' => true,\n                'is_filterable_in_grid' => true,\n                'visible' => true,\n                'is_html_allowed_on_front' => false,\n                'visible_on_front' => true,\n                'used_in_product_listing' => true,\n                'user_defined' => true,\n                'searchable' => false,\n                'filterable' => false,\n                'comparable' => false,\n                'visible_in_advanced_search' => false,\n                'used_for_promo_rules' => false,\n                'wysiwyg_enabled' => false,\n                'is_used_for_price_rules' => false,\n                'backend' => \\Magento\\Catalog\\Model\\Product\\Attribute\\Backend\\Weight::class,\n                'frontend' => '',\n                'class' => '',\n                'source' => '',\n                'default' => null,\n                'note' => 'Product weight including packaging (in weight unit configured in store settings)',\n                'apply_to' => 'simple,configurable,virtual,bundle,downloadable,grouped',\n                'frontend_class' => 'validate-number validate-zero-or-greater'\n            ]\n        );\n    }\n\n    /**\n     * @inheritdoc\n     */\n    public function revert(): void\n    {\n        /** @var EavSetup $eavSetup */\n        $eavSetup = $this->eavSetupFactory->create(['setup' => $this->moduleDataSetup]);\n        $eavSetup->removeAttribute(\n            \\Magento\\Catalog\\Model\\Product::ENTITY,\n            'gross_weight'\n        );\n    }\n\n    /**\n     * @inheritdoc\n     */\n    public static function getDependencies(): array\n    {\n        return [];\n    }\n\n    /**\n     * @inheritdoc\n     */\n    public function getAliases(): array\n    {\n        return [];\n    }\n}",
    "etc/adminhtml/system.xml": "<?xml version=\"1.0\"?>\n<config xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"\n        xsi:noNamespaceSchemaLocation=\"urn:magento:module:Magento_Config:etc/system_file.xsd\">\n    <system>\n        <section id=\"catalog\">\n            <group id=\"product_attributes\" translate=\"label\" type=\"text\" sortOrder=\"100\" showInDefault=\"1\" showInWebsite=\"1\" showInStore=\"1\">\n                <label>Product Attributes</label>\n                <comment><![CDATA[Gross Weight attribute is available for all product types and can be used for shipping calculations.]]></comment>\n            </group>\n        </section>\n    </system>\n</config>",
    "view/adminhtml/ui_component/product_form.xml": "<?xml version=\"1.0\"?>\n<form xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"\n      xsi:noNamespaceSchemaLocation=\"urn:magento:module:Magento_Ui:etc/ui_configuration.xsd\">\n    <fieldset name=\"product-details\">\n        <field name=\"gross_weight\" formElement=\"input\" sortOrder=\"100\">\n            <argument name=\"data\" xsi:type=\"array\">\n                <item name=\"config\" xsi:type=\"array\">\n                    <item name=\"source\" xsi:type=\"string\">product</item>\n                </item>\n            </argument>\n            <settings>\n                <validation>\n                    <rule name=\"validate-number\" xsi:type=\"boolean\">true</rule>\n                    <rule name=\"validate-zero-or-greater\" xsi:type=\"boolean\">true</rule>\n                </validation>\n                <dataType>text</dataType>\n                <label translate=\"true\">Gross Weight</label>\n                <dataScope>gross_weight</dataScope>\n                <notice translate=\"true\">Product weight including packaging</notice>\n            </settings>\n        </field>\n    </fieldset>\n</form>",
    "view/frontend/layout/catalog_product_view.xml": "<?xml version=\"1.0\"?>\n<page xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"\n      xsi:noNamespaceSchemaLocation=\"urn:magento:framework:View/Layout/etc/page_configuration.xsd\">\n    <body>\n        <referenceBlock name=\"product.info.details\">\n            <block class=\"Magento\\Catalog\\Block\\Product\\View\\Description\"\n                   name=\"product.info.gross_weight\"\n                   template=\"Vendor_B2BModule::product/view/gross_weight.phtml\"\n                   group=\"detailed_info\">\n                <arguments>\n                    <argument name=\"title\" translate=\"true\" xsi:type=\"string\">Gross Weight</argument>\n                    <argument name=\"sort_order\" xsi:type=\"string\">20</argument>\n                </arguments>\n            </block>\n        </referenceBlock>\n    </body>\n</page>",
    "view/frontend/templates/product/view/gross_weight.phtml": "<?php\n/**\n * @var \\Magento\\Catalog\\Block\\Product\\View\\Description $block\n * @var \\Magento\\Framework\\Escaper $escaper\n */\n$product = $block->getProduct();\n$grossWeight = $product->getData('gross_weight');\n?>\n<?php if ($grossWeight): ?>\n<div class=\"product-gross-weight\">\n    <div class=\"label\"><?= $escaper->escapeHtml(__('Gross Weight:')) ?></div>\n    <div class=\"value\"><?= $escaper->escapeHtml($grossWeight) ?> <?= $escaper->escapeHtml(__('lbs')) ?></div>\n</div>\n<?php endif; ?>",
    "etc/di.xml": "<?xml version=\"1.0\"?>\n<config xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"\n        xsi:noNamespaceSchemaLocation=\"urn:magento:framework:ObjectManager/etc/config.xsd\">\n    <!-- No plugins needed for attribute creation, handled by data patch -->\n</config>",
    "Test/Unit/Setup/Patch/Data/AddGrossWeightAttributeTest.php": "<?php\ndeclare(strict_types=1);\n\nnamespace Vendor\\B2BModule\\Test\\Unit\\Setup\\Patch\\Data;\n\nuse Magento\\Eav\\Setup\\EavSetup;\nuse Magento\\Eav\\Setup\\EavSetupFactory;\nuse Magento\\Framework\\Setup\\ModuleDataSetupInterface;\nuse PHPUnit\\Framework\\TestCase;\nuse PHPUnit\\Framework\\MockObject\\MockObject;\nuse Vendor\\B2BModule\\Setup\\Patch\\Data\\AddGrossWeightAttribute;\n\n/**\n * Unit test for AddGrossWeightAttribute data patch\n */\nclass AddGrossWeightAttributeTest extends TestCase\n{\n    /**\n     * @var AddGrossWeightAttribute\n     */\n    private AddGrossWeightAttribute $patch;\n\n    /**\n     * @var ModuleDataSetupInterface|MockObject\n     */\n    private ModuleDataSetupInterface|MockObject $moduleDataSetup;\n\n    /**\n     * @var EavSetupFactory|MockObject\n     */\n    private EavSetupFactory|MockObject $eavSetupFactory;\n\n    /**\n     * @var EavSetup|MockObject\n     */\n    private EavSetup|MockObject $eavSetup;\n\n    /**\n     * @inheritdoc\n     */\n    protected function setUp(): void\n    {\n        $this->moduleDataSetup = $this->createMock(ModuleDataSetupInterface::class);\n        $this->eavSetupFactory = $this->createMock(EavSetupFactory::class);\n        $this->eavSetup = $this->createMock(EavSetup::class);\n\n        $this->eavSetupFactory->method('create')\n            ->willReturn($this->eavSetup);\n\n        $this->patch = new AddGrossWeightAttribute(\n            $this->moduleDataSetup,\n            $this->eavSetupFactory\n        );\n    }\n\n    /**\n     * Test that apply method creates gross_weight attribute\n     *\n     * @return void\n     */\n    public function testApply(): void\n    {\n        $this->eavSetup->expects($this->once())\n            ->method('addAttribute')\n            ->with(\n                \\Magento\\Catalog\\Model\\Product::ENTITY,\n                'gross_weight',\n                $this->callback(function ($config) {\n                    return $config['type'] === 'decimal'\n                        && $config['label'] === 'Gross Weight'\n                        && $config['input'] === 'text'\n                        && $config['required'] === false;\n                })\n            );\n\n        $this->patch->apply();\n    }\n\n    /**\n     * Test that revert method removes gross_weight attribute\n     *\n     * @return void\n     */\n    public function testRevert(): void\n    {\n        $this->eavSetup->expects($this->once())\n            ->method('removeAttribute')\n            ->with(\n                \\Magento\\Catalog\\Model\\Product::ENTITY,\n                'gross_weight'\n            );\n\n        $this->patch->revert();\n    }\n\n    /**\n     * Test that getDependencies returns empty array\n     *\n     * @return void\n     */\n    public function testGetDependencies(): void\n    {\n        $this->assertIsArray(AddGrossWeightAttribute::getDependencies());\n        $this->assertEmpty(AddGrossWeightAttribute::getDependencies());\n    }\n\n    /**\n     * Test that getAliases returns empty array\n     *\n     * @return void\n     */\n    public function testGetAliases(): void\n    {\n        $this->assertIsArray($this->patch->getAliases());\n        $this->assertEmpty($this->patch->getAliases());\n    }\n}",
    "README.md": "# Vendor_B2BModule - Gross Weight Attribute\n\n## Overview\nThis module adds a `gross_weight` product attribute to Adobe Commerce that accepts decimal values and is available for all product types.\n\n## Features\n- Decimal attribute type for precise weight measurements\n- Available for all product types (simple, configurable, virtual, bundle, downloadable, grouped)\n- Global scope attribute\n- Visible in admin grid and product form\n- Displayed on product detail page frontend\n- Includes validation for positive numbers\n- Revertable data patch for easy rollback\n\n## Installation\n1. Copy module to `app/code/Vendor/B2BModule`\n2. Run `bin/magento setup:upgrade`\n3. Run `bin/magento setup:di:compile`\n4. Run `bin/magento cache:flush`\n\n## Usage\n### Admin\n- Navigate to Catalog > Products\n- Edit any product\n- Find \"Gross Weight\" field in Product Details section\n- Enter weight value including packaging\n\n### Frontend\n- Gross weight displays on product detail page in \"Detailed Info\" tab\n- Weight unit follows store configuration\n\n## Technical Details\n- Attribute Code: `gross_weight`\n- Type: Decimal\n- Scope: Global\n- Backend Model: `Magento\\Catalog\\Model\\Product\\Attribute\\Backend\\Weight`\n- Validation: validate-number, validate-zero-or-greater\n\n## Testing\nRun unit tests:\n```bash\nbin/magento dev:tests:run unit --filter AddGrossWeightAttributeTest\n```\n\n## Rollback\nTo remove the attribute:\n```bash\nbin/magento module:uninstall Vendor_B2BModule\n```"
  },
  "extension_point": "patch",
  "explanation": "Created a Data Patch to add a decimal 'gross_weight' product attribute available for all product types, as attribute creation requires EAV setup via data patches rather than plugins or observers."
